package net.civeira.phylax.common.crypto;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.SecureRandom;
import java.util.Arrays;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;

import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;

/** AES-256-GCM key ring interoperable with PHP KeyRingSecretStorage. */
@ApplicationScoped
public class KeyRingSecretStorage {
  public static final String SEALED_PREFIX = "sealed:";
  private static final String INFO = "lughauth/reversible-secret-storage/";
  private final SecureRandom random = new SecureRandom();
  private final Map<String, byte[]> keys = new LinkedHashMap<>();
  private final String current;

  public KeyRingSecretStorage(
      @ConfigProperty(name = "security.secrets.keys", defaultValue = "") String configured,
      @ConfigProperty(name = "security.secrets.current", defaultValue = "") String current) {
    Map<String, String> secrets = new LinkedHashMap<>();
    for (String entry : configured.split(",")) {
      String[] pair = entry.trim().split(":", 2);
      if (pair.length == 2 && pair[0].matches("[a-zA-Z0-9_-]{1,32}") && !pair[1].isEmpty()) {
        secrets.put(pair[0], pair[1]);
      }
    }
    if (secrets.isEmpty()) {
      secrets.put("k0", "clave-cifrado");
    }
    this.current = current.isEmpty() ? secrets.keySet().iterator().next() : current;
    if (!secrets.containsKey(this.current)) {
      throw new IllegalArgumentException("Current encryption key is not in the key ring");
    }
    secrets.forEach((id, secret) -> keys.put(id, derive(secret, INFO + id)));
  }

  public String seal(String plain, String context) {
    try {
      byte[] iv = new byte[12];
      random.nextBytes(iv);
      Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
      cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(keys.get(current), "AES"),
          new GCMParameterSpec(128, iv));
      cipher.updateAAD(context.getBytes(StandardCharsets.UTF_8));
      byte[] encrypted = cipher.doFinal(plain.getBytes(StandardCharsets.UTF_8));
      return SEALED_PREFIX + current + ":" + Base64.getUrlEncoder().withoutPadding().encodeToString(
          ByteBuffer.allocate(iv.length + encrypted.length).put(iv).put(encrypted).array());
    } catch (GeneralSecurityException ex) {
      throw new IllegalStateException("Unable to seal secret", ex);
    }
  }

  public String open(String sealed, String context) {
    String[] parts = parse(sealed);
    try {
      byte[] payload = Base64.getUrlDecoder().decode(parts[1]);
      if (payload.length < 28) {
        throw new IllegalArgumentException("Malformed sealed secret");
      }
      Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
      cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(keys.get(parts[0]), "AES"),
          new GCMParameterSpec(128, Arrays.copyOf(payload, 12)));
      cipher.updateAAD(context.getBytes(StandardCharsets.UTF_8));
      return new String(cipher.doFinal(payload, 12, payload.length - 12), StandardCharsets.UTF_8);
    } catch (GeneralSecurityException | IllegalArgumentException ex) {
      throw new IllegalArgumentException("Unable to open sealed secret", ex);
    }
  }

  public boolean needsReseal(String sealed) {
    return !current.equals(parse(sealed)[0]);
  }

  public static boolean isSealed(String stored) {
    return stored != null && stored.startsWith(SEALED_PREFIX);
  }

  private String[] parse(String sealed) {
    if (!isSealed(sealed)) {
      throw new IllegalArgumentException("Not a sealed secret");
    }
    String[] parts = sealed.substring(SEALED_PREFIX.length()).split(":", 2);
    if (parts.length != 2 || !keys.containsKey(parts[0])) {
      throw new IllegalArgumentException("Unknown key for sealed secret");
    }
    return parts;
  }

  /** PHP hash_hkdf('sha256', secret, 32, info): extract with 32 zero bytes, then expand. */
  private static byte[] derive(String secret, String info) {
    try {
      Mac mac = Mac.getInstance("HmacSHA256");
      mac.init(new SecretKeySpec(new byte[32], "HmacSHA256"));
      byte[] prk = mac.doFinal(secret.getBytes(StandardCharsets.UTF_8));
      mac.init(new SecretKeySpec(prk, "HmacSHA256"));
      return mac.doFinal(ByteBuffer.allocate(info.getBytes(StandardCharsets.UTF_8).length + 1)
          .put(info.getBytes(StandardCharsets.UTF_8)).put((byte) 1).array());
    } catch (GeneralSecurityException ex) {
      throw new IllegalStateException("HKDF-SHA256 is unavailable", ex);
    }
  }
}
